import { decode } from '@jridgewell/sourcemap-codec'

/** The parts of a version 3 source map that attribution reads. */
export interface RawSourceMap {
  sources: (string | null)[]
  sourceRoot?: string
  mappings: string
}

/** Generated bytes per original source. Every byte of the code is counted exactly once. */
export interface Attribution {
  /** Raw bytes by source path as written in the map, with `sourceRoot` applied. */
  bySource: Map<string, number>
  /** Bytes before the first mapping of a line, of unmapped segments, and line breaks. */
  unmapped: number
}

const encoder = new TextEncoder()
const utf8Length = (text: string) =>
  /^\p{ASCII}*$/u.test(text) ? text.length : encoder.encode(text).length

/**
 * Attributes every UTF-8 byte of generated `code` to the original source of the mapping segment
 * that covers it. A segment covers its column up to the next segment on the same line, or the
 * end of the line. Index maps with `sections` are not supported and count as unmapped.
 */
export function attributeSourceMap(code: string, map: RawSourceMap): Attribution {
  const bySource = new Map<string, number>()
  let unmapped = 0
  if (typeof map.mappings !== 'string' || !Array.isArray(map.sources)) {
    return { bySource, unmapped: utf8Length(code) }
  }

  const root = map.sourceRoot ? map.sourceRoot.replace(/\/?$/, '/') : ''
  const sources = map.sources.map((source) => (source == null ? undefined : root + source))
  const decoded = decode(map.mappings)
  const lines = code.split('\n')

  lines.forEach((line, index) => {
    if (index < lines.length - 1) unmapped += 1
    const segments = (decoded[index] ?? []).toSorted((a, b) => a[0] - b[0])
    let covered = 0
    let previousSource: string | undefined
    const add = (end: number) => {
      if (end <= covered) return
      const bytes = utf8Length(line.slice(covered, end))
      if (previousSource === undefined) unmapped += bytes
      else bySource.set(previousSource, (bySource.get(previousSource) ?? 0) + bytes)
      covered = end
    }
    for (const segment of segments) {
      add(Math.min(segment[0], line.length))
      previousSource = segment[1] === undefined ? undefined : sources[segment[1]]
    }
    add(line.length)
  })
  return { bySource, unmapped }
}
